package com.ems.controller;
import com.ems.dao.AdminDAO; import com.ems.model.Admin; import com.ems.util.BCryptUtil; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/login") public class LoginServlet extends HttpServlet { protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if(r.getSession(false)!=null&&r.getSession(false).getAttribute("adminUser")!=null){s.sendRedirect(r.getContextPath()+"/dashboard");return;}r.getRequestDispatcher("/WEB-INF/views/login.jsp").forward(r,s);} protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String u=r.getParameter("username"),p=r.getParameter("password");try{Admin a=new AdminDAO().findByUsername(u);if(a!=null&&BCryptUtil.matches(p,a.passwordHash())){HttpSession old=r.getSession(false);if(old!=null)old.invalidate();HttpSession session=r.getSession(true);session.setMaxInactiveInterval(30*60);session.setAttribute("adminUser",a.username());s.sendRedirect(r.getContextPath()+"/dashboard");}else{r.setAttribute("error","Invalid username or password.");doGet(r,s);}}catch(Exception e){getServletContext().log("Login failed",e);r.setAttribute("error","Unable to sign in right now.");doGet(r,s);}} }
